/**
 * Create GitHub Releases for package version tags.
 *
 * Used by `scripts/release-changed.mjs` after tags are pushed. Packages are
 * also published to npmjs via Trusted Publishing in the same release job.
 * Release notes are generated by `gh release create --generate-notes`.
 * The same release commit also prepends a bump summary to CHANGELOG.md.
 */
import { execFileSync } from 'node:child_process';

/**
 * @typedef {'major' | 'minor' | 'patch'} Increment
 * @typedef {{
 *   name: string,
 *   version: string,
 *   next: string,
 *   increment: Increment,
 *   tag: string,
 *   previousTag?: string | null,
 * }} ReleaseSpec
 */

/**
 * @param {ReleaseSpec} release
 * @returns {string}
 */
export function formatReleaseTitle(release) {
  return `${release.name}@${release.next}`;
}

/**
 * Extra notes prepended to GitHub's generated notes: bump summary + npm link.
 * `gh release create --generate-notes` supplies the commit list.
 * @param {ReleaseSpec} release
 * @returns {string}
 */
export function formatReleaseNotes(release) {
  const bumpLine =
    release.version === release.next
      ? `## ${release.name} \`${release.next}\``
      : `## ${release.name} \`${release.version}\` → \`${release.next}\` (${release.increment})`;
  const npmUrl = `https://www.npmjs.com/package/${release.name}/v/${release.next}`;

  return [
    bumpLine,
    '',
    `📦 [\`${release.name}@${release.next}\`](${npmUrl})`,
    '',
    `Install: \`pnpm add ${release.name}@${release.next}\``,
    '',
    'GitHub Releases include generated commit notes. The matching `CHANGELOG.md` bump lands on `main` in the same release commit.',
  ].join('\n');
}

/**
 * Arguments for `gh release create` (generated notes + package summary).
 * @param {ReleaseSpec} release
 * @returns {string[]}
 */
export function githubReleaseCreateArgs(release) {
  /** @type {string[]} */
  const args = [
    'release',
    'create',
    release.tag,
    '--verify-tag',
    '--generate-notes',
    '--title',
    formatReleaseTitle(release),
    '--notes',
    formatReleaseNotes(release),
  ];
  if (typeof release.previousTag === 'string' && release.previousTag) {
    args.push('--notes-start-tag', release.previousTag);
  }
  return args;
}

/**
 * True when `gh release view` failed because the Release does not exist yet.
 * @param {unknown} err
 */
export function isReleaseNotFoundError(err) {
  const text = [
    err instanceof Error ? err.message : String(err),
    err && typeof err === 'object' && 'stderr' in err ? String(err.stderr) : '',
  ]
    .join('\n')
    .toLowerCase();

  return (
    text.includes('release not found') ||
    text.includes('could not find') ||
    text.includes('not found') ||
    text.includes('http 404')
  );
}

/**
 * @param {(args: string[]) => string} runGh
 * @param {string} tag
 * @returns {boolean}
 */
export function githubReleaseExists(runGh, tag) {
  try {
    runGh(['release', 'view', tag, '--json', 'tagName']);
    return true;
  } catch (err) {
    if (isReleaseNotFoundError(err)) {
      return false;
    }
    throw err;
  }
}

/**
 * Subprocess env for `gh release`. The App token is GH_TOKEN only — never
 * leave RELEASE_APP_TOKEN or the job GITHUB_TOKEN on the child.
 *
 * @param {string} ghToken
 * @param {NodeJS.ProcessEnv} [base]
 * @returns {NodeJS.ProcessEnv}
 */
export function envForGitHubCli(ghToken, base = process.env) {
  if (!ghToken) {
    throw new Error('App token is required for gh release. Pass it only to the gh subprocess.');
  }
  const env = { ...base };
  delete env.RELEASE_APP_TOKEN;
  delete env.GITHUB_TOKEN;
  env.GH_TOKEN = ghToken;
  return env;
}

/**
 * @param {string} [ghToken]
 * @returns {(args: string[]) => string}
 */
function defaultRunGh(ghToken) {
  return (args) =>
    execFileSync('gh', args, {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      env: envForGitHubCli(ghToken ?? ''),
    }).trim();
}

/**
 * Create one GitHub Release per package tag. Skips tags that already have a Release.
 *
 * @param {ReleaseSpec[]} releases
 * @param {{
 *   runGh?: (args: string[]) => string,
 *   log?: (msg: string) => void,
 *   ghToken?: string,
 * }} [options]
 * @returns {{ created: string[], skipped: string[] }}
 */
export function createGitHubReleases(releases, options = {}) {
  const runGh = options.runGh ?? defaultRunGh(options.ghToken);
  const log = options.log ?? console.log;

  /** @type {string[]} */
  const created = [];
  /** @type {string[]} */
  const skipped = [];

  for (const release of releases) {
    if (githubReleaseExists(runGh, release.tag)) {
      log(`GitHub Release already exists for ${release.tag}; skipping.`);
      skipped.push(release.tag);
      continue;
    }

    runGh(githubReleaseCreateArgs(release));
    log(`Created GitHub Release for ${release.tag}.`);
    created.push(release.tag);
  }

  return { created, skipped };
}
